def is_good(n):
    s_n = str(n)
    if len(s_n) == 1:
        return True
    for i in range(len(s_n)):
        new_s = s_n[:i] + s_n[i+1:]
        if not new_s: continue
        new_n = int(new_s)
        if n % new_n == 0 and is_good(new_n):
            return True
    return False

